import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十卦 履 天澤履 乾上兌下","description":"周易 - 第十卦 履 天澤履 乾上兌下","frontmatter":{"title":"第十卦 履 天澤履 乾上兌下","description":"周易 - 第十卦 履 天澤履 乾上兌下"},"headers":[],"relativePath":"classics/zhouyi/011.md","filePath":"classics/zhouyi/011.md"}'),l={name:"classics/zhouyi/011.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="履" tabindex="-1">履 <a class="header-anchor" href="#履" aria-label="Permalink to “履”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>履虎尾，不咥人，亨。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>履，柔履剛也。說而應乎乾，是以履虎尾，不咥人，亨。剛中正，履帝位而不疚，光明也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>上天下澤，履；君子以辨上下，安民志。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>素履，往無咎。象曰：素履之 往，獨行願也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>履道坦坦，幽人貞吉。象曰：幽人貞吉，中不自亂也。</p><h3 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h3><p>眇能視，跛能履，履虎尾，咥人，兇。武人為於大君。象曰：眇能視；不足以有明也。跛能履；不足以與行也。咥人之兇；位不當也。武人為於大君；志剛也。</p><h3 id="九四" tabindex="-1">九四 <a class="header-anchor" href="#九四" aria-label="Permalink to “九四”">​</a></h3><p>履虎尾，愬愬終吉。象曰：愬愬終吉，志行也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>夬履，貞厲。象曰：夬履貞厲，位正當也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>視履考祥，其旋元吉。象曰：元吉在上，大有慶也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
